export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();
  private readonly schemaCompiler = new Ajv({
    allErrors: true,
    format: false,
    unknownFormats: 'ignore',
    coerceTypes: false,
    useDefaults: false,
    removeAdditional: false,
  });

  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    this.resolveValidator(tool);
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private resolveValidator(tool: StoredTool): ValidateFunction {
    if (tool.validator) return tool.validator;
    const resolved = this.resolveDefinition(tool.definitionSource);
    const cachedValidator = this.dynamicValidators.get(resolved.inputSchema);
    if (cachedValidator) return cachedValidator;
    const compiledValidator = compileSchema(this.schemaCompiler, resolved.name, resolved.inputSchema);
    this.dynamicValidators.set(resolved.inputSchema, compiledValidator);
    return compiledValidator;
  }
}

function compileSchema(
  compiler: InstanceType<typeof Ajv>,
  toolName: string,
  schema: Record<string, unknown>
): ValidateFunction {
  try {
    return compiler.compile(schema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Tool "${toolName}" has an uncompilable inputSchema: ${reason}`, {cause: error});
  }
}

